{
  "application": "poster-generation",
  "case_id": "case-edu-global-education-progress-comparison",
  "language": "en",
  "source_brief": "/app/benchmark/source_brief.md",
  "poster": {
    "aspect_ratio": "A1-portrait",
    "audience": "public-exhibition",
    "tone": "data-forward, engaging",
    "venue": null
  },
  "brief": {
    "title": "The State of Global Education: Progress, Gaps, and Inequality",
    "one_liner": "A comparative look at how far the world has come in expanding education access — and the critical gaps that remain in quality, attendance, and equity.",
    "goal": "Viewers should understand that while global education access has dramatically improved over two centuries, hundreds of millions of children still miss out on schooling, and many who attend school fail to achieve basic literacy — with stark disparities between rich and poor countries."
  },
  "sections": [
    {
      "id": "historical-progress",
      "title": "Two Centuries of Educational Expansion",
      "objective": "Show the dramatic reversal from 1800 (fewer than 1 in 5 adults educated) to today (more than 4 in 5 adults educated)."
    },
    {
      "id": "learning-crisis",
      "title": "The Learning Crisis: Enrollment ≠ Learning",
      "objective": "Highlight that in many low-income countries, fewer than 20% of children achieve minimum reading proficiency by the end of primary school."
    },
    {
      "id": "out-of-school",
      "title": "244 Million Children Still Out of School",
      "objective": "Convey the scale of children missing from primary and secondary education globally, with secondary dropouts as a major driver."
    },
    {
      "id": "quality-inequality",
      "title": "Learning-Adjusted Years of Schooling: A World Divided",
      "objective": "Compare the fewer than 3 years of quality schooling in the poorest countries against 10+ years in rich countries."
    },
    {
      "id": "gender-gap",
      "title": "Closing the Gender Gap",
      "objective": "Show that globally the gender gap has nearly closed, with women now more likely to enroll in tertiary education, while noting exceptions like Afghanistan."
    }
  ],
  "metrics": [
    {
      "label": "Adults with basic education (1800)",
      "value": "< 1 in 5"
    },
    {
      "label": "Adults with basic education (today)",
      "value": "> 4 in 5"
    },
    {
      "label": "Children out of school (2023)",
      "value": "244 million"
    },
    {
      "label": "Reading proficiency in low-income countries",
      "value": "< 20%"
    },
    {
      "label": "Quality schooling in poorest countries",
      "value": "< 3 years"
    },
    {
      "label": "Quality schooling in richest countries",
      "value": "10+ years"
    }
  ]
}

