<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>State of Global Education - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body {
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #0f172a;
    }
    #container {
      width: 100%;
      height: 100%;
    }
    #export-btn {
      position: fixed;
      top: 20px;
      right: 20px;
      padding: 12px 24px;
      background: #f59e0b;
      color: #0f172a;
      border: none;
      border-radius: 8px;
      font-size: 16px;
      font-weight: 600;
      cursor: pointer;
      z-index: 1000;
    }
    #export-btn:hover { background: #fbbf24; }
  </style>
</head>
<body>
  <button id="export-btn">Export PNG</button>
  <div id="container"></div>
  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    const infographic = new AntVInfographic.Infographic({
      container: '#container',
      width: 794,
      height: 1123,
    });

    const syntax = `infographic compare-binary-horizontal-badge-card-arrow
data
  title The State of Global Education
  desc Progress, Gaps, and Inequality
  compares
    - label HISTORICAL PROGRESS
      children
        - label 1800 — Less than 1 in 5 adults educated
          icon user
          value 20
        - label Today — More than 4 in 5 adults educated
          icon users
          value 80
    - label 244 MILLION CHILDREN OUT OF SCHOOL
      children
        - label Primary age out of school
          icon book
          value 60
        - label Secondary age out of school
          icon graduation cap
          value 184
    - label QUALITY DIVIDE
      children
        - label Poorest countries — Less than 3 years of quality schooling
          icon alert circle
          value 3
        - label Richest countries — 10+ years of quality schooling
          icon check circle
          value 10
theme
  palette #0f172a #f59e0b #ef4444 #22c55e #3b82f6 #94a3b8
  base
    background #0f172a
    text font-family Impact, sans-serif
  stylize
    rough`;

    infographic.render(syntax);

    document.fonts?.ready.then(() => {
      infographic.render(syntax);
    }).catch((error) => console.error('Error:', error));

    document.getElementById('export-btn').addEventListener('click', async () => {
      try {
        const dataUrl = await infographic.toDataURL({ type: 'png', pixelRatio: 2 });
        const link = document.createElement('a');
        link.download = 'global-education-poster.png';
        link.href = dataUrl;
        link.click();
      } catch (error) {
        console.error('Export failed:', error);
        alert('Export failed: ' + error.message);
      }
    });
  </script>
</body>
</html>", "structuredPatch": [], "originalFile": null, "userModified": false}

