const puppeteer = require('puppeteer');
const path = require('path');
const fs = require('fs');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();

  const htmlPath = path.join(__dirname, 'global-education-infographic.html');
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle0' });

  // Wait for fonts and rendering
  await page.waitForTimeout(2000);

  // Get the container element dimensions
  const containerBox = await page.evaluate(() => {
    const container = document.getElementById('container');
    const svg = container.querySelector('svg');
    if (svg) {
      return { width: svg.clientWidth, height: svg.clientHeight };
    }
    return { width: 794, height: 1123 };
  });

  console.log('Container size:', containerBox);

  // Set the viewport to match A1 portrait (794 x 1123 at 96 DPI)
  await page.setViewport({
    width: Math.max(containerBox.width, 794),
    height: Math.max(containerBox.height, 1123)
  });

  // Screenshot the container
  const screenshot = await page.evaluate(() => {
    const container = document.getElementById('container');
    const svg = container.querySelector('svg');
    if (svg) {
      const svgData = new XMLSerializer().serializeToString(svg);
      const svgBlob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
      const url = URL.createObjectURL(svgBlob);
      return url;
    }
    return null;
  });

  if (screenshot) {
    console.log('SVG captured successfully');
  }

  // Create output directory
  const outputDir = path.join(__dirname, 'output');
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Get the full page screenshot
  const fullPage = await page.screenshot({
    type: 'png',
    fullPage: false,
    clip: {
      x: 0,
      y: 0,
      width: containerBox.width || 794,
      height: containerBox.height || 1123
    }
  });

  fs.writeFileSync(path.join(outputDir, 'final_poster.png'), fullPage);
  console.log('Poster saved to output/final_poster.png');

  await browser.close();
})();

